 async function refresh(){
  if(!user)return;
  const [c,i,w,p,t,me,pa,ml,mr]=await Promise.all([
   supabase.from('cards').select('*').order('created_at',{ascending:false}),
   supabase.from('inventory').select('id,card_id,quantity,cards(*)').eq('user_id',user.id),
   supabase.from('wallets').select('balance,last_income_at').eq('user_id',user.id).single(),
   supabase.from('profiles').select('id,username').order('username'),
   supabase.from('trades').select('*,sender:profiles!trades_sender_profile_fkey(username),receiver:profiles!trades_receiver_profile_fkey(username),trade_items(*,cards(*))').or('sender_id.eq.'+user.id+',receiver_id.eq.'+user.id).order('created_at',{ascending:false}),
   supabase.rpc('is_cardsnoscam_admin'),
   supabase.from('packs').select('*').order('price'),
   supabase.from('market_listings').select('*,cards(*)').eq('active',true).order('created_at',{ascending:false}),
   supabase.from('market_requests').select('*,listing:market_listings(*,cards(*))').order('created_at',{ascending:false})
  ]);
  // Fail visibly if any required game data could not be loaded. Silent partial
  // refreshes made the market, wallet or trades appear empty when RLS/API failed.
  const failed=[c,i,w,p,t,me,pa,ml,mr].find(result=>result.error);
  if(failed?.error)throw failed.error;

  if(!w.data)throw new Error('Dein Coin-Konto konnte nicht geladen werden. Bitte melde dich erneut an.');
  const walletData=w.data;
  const catalog=(c.data||[]) as Card[];
  const owned=(i.data||[]) as any[];
  setCards(catalog);
  setInventory(owned.map(item=>({
   ...item,
   cards:Array.isArray(item.cards)?item.cards[0]:item.cards||catalog.find(card=>card.id===item.card_id)
  })));
  setWallet(Number(walletData.balance));
  setLastIncomeAt(walletData.last_income_at?new Date(walletData.last_income_at).getTime():Date.now());
  setProfiles(p.data||[]);
  setTrades(t.data||[]);
  setAdmin(Boolean(me.data));
  setPacks(pa.data||[]);
  setMarketListings(ml.data||[]);
  setMarketRequests(mr.data||[]);
 }
