 async function revealDelay(ms:number){const start=Date.now();while(Date.now()-start<ms&&!skipRevealRef.current)await new Promise(r=>setTimeout(r,35));}
 function stopCardSound(){if(cardAudioRef.current){cardAudioRef.current.pause();try{cardAudioRef.current.currentTime=0;}catch{}}cardSoundDoneRef.current?.();cardSoundDoneRef.current=null;}
 function unlockCardSound(){try{if(!cardAudioRef.current){const audio=new Audio();audio.preload='auto';cardAudioRef.current=audio;audio.src='data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=';void audio.play().catch(()=>{});}}catch{}}
