 function openCardDetails(card:Card){void playCardSound(card);setSelectedCard(card);}
 async function openPack(packId:string){unlockCardSound();const pack=packs.find((p:any)=>p.id===packId);const single=Number(pack?.card_count||1)===1;skipRevealRef.current=false;setBusy(true);setLastPull([]);setRevealCardVisible(false);setRevealStep(0);setPackStage(single?1:0);try{if(single){await revealDelay(520);setPackStage(2);await revealDelay(620);setPackStage(3);await revealDelay(520);}const {data,error}=await supabase.rpc('open_card_pack',{p_pack_id:packId});if(error)throw error;const rows=Array.isArray(data)?data:[data];const pulledIds=rows.map((row:any)=>row?.card_id).filter(Boolean);const {data:pulledData,error:pulledError}=await supabase.from('cards').select('*').in('id',pulledIds);if(pulledError)throw pulledError;const pulled=(pulledData||[]) as Card[];setLastPull(pulled);await refresh();const {data:missionData}=await supabase.from('player_mission_progress').select('*').eq('user_id',user.id);setMissionRows(missionData||[]);notify('BOOM! Du hast '+rows.length+' Karte'+(rows.length===1?'':'n')+' gezogen!');if(single&&pulled[0]){setPackStage(4);const tags=pulled[0].highlights||[];if(!skipRevealRef.current){await revealDelay(650);setRevealStep(1);await revealDelay(650);setRevealStep(2);await revealDelay(450);for(let i=0;i<tags.length;i++){setRevealStep(3+i);await revealDelay(520);}}setRevealCardVisible(true);setRevealStep(99);if(pulled[0].audio_url&&!skipRevealRef.current){await revealDelay(100);if(!skipRevealRef.current)await playCardSound(pulled[0]);}}}catch(e){fail(e)}finally{skipRevealRef.current=false;setPackStage(0);setShowRevealClip(false);setBusy(false)}}
 async function startAudioRecording(){try{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined')throw new Error('Audioaufnahme wird von diesem Browser nicht unterstützt.');const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);audioChunksRef.current=[];recorder.ondataavailable=e=>{if(e.data.size)audioChunksRef.current.push(e.data)};recorder.onstop=()=>{const blob=new Blob(audioChunksRef.current,{type:recorder.mimeType||'audio/webm'});setRecordedAudio(blob);stream.getTracks().forEach(track=>track.stop());setRecording(false)};recorderRef.current=recorder;recorder.start();setRecording(true);notify('Aufnahme läuft. Drücke auf Aufnahme stoppen, wenn du fertig bist.');}catch(e){fail(e)}}
